# Loaded into kernels generated by lua/notebook/kernel.lua
# (--IPKernelApp.exec_files). matplotlib reads $MATPLOTLIBRC (written by
# lua/notebook/plots.lua) when it is imported; this hook re-applies that file
# before a cell when Neovim has rewritten it (plot paper toggled, colorscheme
# changed), so the change shows on the next plot without a kernel restart.


def _nvim_plot_style():
    import os
    import sys

    from IPython import get_ipython

    rc = os.environ.get("MATPLOTLIBRC")
    ip = get_ipython()
    if not rc or ip is None:
        return
    seen: list[int | None] = [None]

    def mtime():
        try:
            return os.stat(rc).st_mtime_ns
        except OSError:
            return None

    def apply(*_):
        # Track the file before every cell, imported or not: the import reads
        # the version seen before its cell, so a style the user sets right
        # after importing isn't overridden, while a later rewrite is applied.
        m, last = mtime(), seen[0]
        seen[0] = m
        if "matplotlib" not in sys.modules or m is None or m == last:
            return
        import matplotlib as mpl  # pyright: ignore[reportMissingImports]

        mpl.rcParams.update(mpl.rc_params_from_file(rc, use_default_template=False))

    ip.events.register("pre_run_cell", apply)


_nvim_plot_style()
del _nvim_plot_style
